r_date) ,lower(coalesce(a.channel,s.channel)))) as total_orders ,safe_divide(total_quantity, count(1) over (partition by coalesce(a.date,s.order_date) ,lower(coalesce(a.channel,s.channel)))) as total_quantity ,safe_divide(s.paid_sales, count(1) over (partition by coalesce(a.date,s.order_date), lower(coalesce(a.channel,s.channel)))) as paid_sales ,safe_divide(s.organic_sales, count(1) over (partition by coalesce(a.date,s.order_date), lower(coalesce(a.channel,s.channel)))) as organic_sales ,safe_divide(s.paid_orders, count(1) over (partition by coalesce(a.date,s.order_date), lower(coalesce(a.channel,s.channel)))) as paid_orders ,safe_divide(s.organic_orders, count(1) over (partition by coalesce(a.date,s.order_date), lower(coalesce(a.channel,s.channel)))) as organic_orders from prolicious-wh.Maplemonk.prolicious_dtc_MARKETING_CONSOLIDATED_INTERMEDIATE a full outer join (select cast(order_timestamp as date) date ,final_utm_campaign campaign_name ,upper(case when lower(final_utm_channel) like any (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\') then \'FACEBOOK\' when lower(final_utm_channel) like (\'%google%\') then \'GOOGLE\' end) channel ,sum(total_sales) shopify_revenue from prolicious-wh.Maplemonk.prolicious_wh_SHOPIFY_FACT_ITEMS where final_utm_channel is not null group by 1,2,3 ) b on lower(a.campaign_name) = lower(b.campaign_name) and a.date = b.date and lower(a.channel) = lower(b.channel) left join (select date(order_date) as order_date, upper(case when lower(CHANNEL) like any (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\',\'%meta%\') then \'FACEBOOK\' when lower(CHANNEL) like (\'%google%\') then \'GOOGLE\' else lower(CHANNEL) end) channel, sum(case when upper(final_channel_type) = \'PAID\' then ifnull(selling_price,0) else 0 end) as paid_sales, count(distinct case when upper(final_channel_type) = \'PAID\' then reference_code end) as paid_orders, sum(case when upper(final_channel_type) = \'PAID\' then ifnull(quantity,0) 